125	  @VisibleForTesting
126	  static PathFragment getShellExecutableForOs(OS os, ShellConfiguration.Options options) {
127	    // TODO(ulfjack): instead of using the OS Bazel runs on, we need to use the exec platform,
128	    // which may be different for remote execution. For now, this can be overridden with
129	    // --shell_executable, so at least there's a workaround.
130	    return getDefaultPathFromOptions(options) != null
131	        ? getDefaultPathFromOptions(options)
132	        : SHELL_EXECUTABLE.getOrDefault(os, FALLBACK_SHELL);
133	  }
